"""Unit 12: Tagalog Basic Course, Semester I, Unit 3, Chapter 3, Lesson 2: Shopping for Food and Other Consumable Goods.
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (Teacher Edition, December 2020).
Audio, pictures, partner and group work are left out; prices are written in words in the spoken lines
and with the peso sign in the English notes, and the book's answer keys are used (misprints are noted)."""
from dsl_tl import *


def dd(xs, ans, n=3, extra=()):
    out = []
    for x in list(xs) + list(extra):
        if x != ans and x not in out:
            out.append(x)
    return out[:n]


def P(n):
    return f"₱{n}"


